seed.products.push(...additionalProducts);
seed.showcases[0].items.push(...additionalProducts.map(p=>p.id));
seed.demoCatalogVersion=2;
function removeInventory(data){
 for(const product of data.products)delete product.quantity;
 return data;
}
function upgradeCatalog(data){
 removeInventory(data);
 if((data.demoCatalogVersion||1)>=2)return data;
 const missing=additionalProducts.filter(p=>!data.products.some(existing=>existing.id===p.id));
 data.products.push(...structuredClone(missing));
 const demo=data.showcases.find(s=>s.id==='s1');
 if(demo)for(const p of additionalProducts)if(!demo.items.includes(p.id))demo.items.push(p.id);
 data.demoCatalogVersion=2;return data;
}
