// Assign emojis once per child. For the same surname and first initial, use distinct emojis.
function displayChildName(child){const [surname,givenName]=child.name.trim().split(/\s+/);return surname+' '+Array.from(givenName)[0]+' '+child.emoji}
function initials(name){return name.split(' ').slice(0,2).map(n=>n[0]).join('')}
function normalize(v){return v.toLocaleLowerCase('ru').replace(/ё/g,'е')}
function listChildren(){
 const term=normalize(query.trim()),list=$('#child-list'),input=$('#search');
 const matches=term?children.filter(c=>normalize(c.name).includes(term)||normalize(displayChildName(c)).includes(term)):[];
 const show=!!term&&selected===null;
 list.hidden=!show;input.setAttribute('aria-expanded',String(show));
 if(!show){list.innerHTML='';return}
 list.innerHTML=matches.map(c=>'<button class="child" data-child="'+c.id+'"><span class="avatar">'+initials(c.name)+'</span><span><strong>'+esc(displayChildName(c))+'</strong><small>'+esc(c.groups.join(' · '))+'</small></span><span class="chevron">›</span></button>').join('')||'<div class="empty">Никого не нашли.<br>Попробуйте другую часть ФИО.</div>';
}
function profile(){const c=children.find(c=>c.id===selected);$('#profile').hidden=!c;if(!c){$('#profile').innerHTML='';return}const balance=c.history.reduce((s,t)=>s+t[2],0);$('#profile').innerHTML='<section class="panel"><div class="profile-head"><span class="avatar">'+initials(c.name)+'</span><div><h2>'+esc(displayChildName(c))+'</h2><p>Карточка ребёнка</p></div></div><div class="balance"><div><div class="balance-label">Текущий счёт</div><div class="balance-value">'+balance.toLocaleString('ru')+'<small>КК</small></div></div><div class="coin" aria-hidden="true">КК</div></div><div class="groups"><span class="muted">Твои группы</span>'+c.groups.map(g=>'<span class="group">'+esc(g)+'</span>').join('')+'</div></section><section class="panel history"><div class="history-heading"><h2>История начислений и списаний</h2><span class="muted">'+c.history.length+' операций</span></div><div class="transactions">'+c.history.map(t=>'<div class="transaction"><span class="operation '+(t[2]<0?'minus':'')+'">'+(t[2]<0?'↗':'↙')+'</span><div><strong>'+esc(t[2]<0?'Списание за товар: '+t[1]:'Начисление')+'</strong><small>'+new Date(t[0]+'T12:00:00Z').toLocaleDateString('ru',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})+'</small></div><div class="amount '+(t[2]<0?'negative':'')+'">'+(t[2]>0?'+':'−')+Math.abs(t[2])+'<small>КК</small></div></div>').join('')+'</div></section>'}
function productCard(p){return '<article class="product"><div class="product-art">'+art(p)+'</div><div class="product-body"><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><div class="product-bottom"><span class="price">'+p.price+' <small>КК</small></span></div></div></article>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#admin-entry').textContent=admin?(page==='admin'?'Админ · Выйти ↗':'Панель администратора ↗'):'Для администратора ↗';if(page==='account'){
 $('#app').innerHTML='<section class="panel search-instructions" aria-label="Инструкция по поиску"><p class="note" id="search-help">Введи фамилию или часть ФИО и выбери ребёнка из результатов поиска. Ниже появятся его счёт КК, группы и история начислений и списаний.</p></section><section class="panel account-search"><h1>Выберите ребёнка</h1><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Введи свое ФИО" aria-label="Введи свое ФИО" aria-describedby="search-help" aria-controls="child-list" aria-expanded="false" autocomplete="off" value="'+esc(query)+'"></div><div class="child-list" id="child-list" hidden></div></section><div class="account-profile" id="profile" hidden></div>';
 listChildren();profile();$('#search').addEventListener('input',e=>{query=e.target.value;selected=null;listChildren();profile()});
 $('#search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!$('#child-list').hidden){const first=$('#child-list button');if(first){e.preventDefault();first.focus()}}});
}else if(page==='store'){const s=db.showcases.find(s=>s.id===db.published),products=s?s.items.map(id=>db.products.find(p=>p.id===id)).filter(Boolean):[];$('#app').innerHTML='<div class="intro"><div><h1>Витрина товаров</h1><p>Награды за старание и новые открытия.</p></div>'+(s?'<span class="tag store-head"><i class="dot"></i>'+esc(s.name)+'</span>':'')+'</div>'+(products.length?'<section class="store"><div class="product-grid">'+products.map(productCard).join('')+'</div></section>':'<div class="panel empty">'+(s?'В этой витрине пока нет товаров.':'Витрина пока не опубликована.')+'</div>')}else if(admin)renderAdmin();else{page='account';render()}}
function renderAdmin(){$('#app').innerHTML='<div class="intro"><div><h1>Редактор витрины</h1><p>Товары и витрины</p></div><button class="primary" data-action="'+(adminTab==='products'?'add-product':'add-showcase')+'">+ '+(adminTab==='products'?'Добавить товар':'Добавить витрину')+'</button></div><div class="admin-tabs"><button data-tab="products" class="'+(adminTab==='products'?'active':'')+'">Все товары</button><button data-tab="showcases" class="'+(adminTab==='showcases'?'active':'')+'">Редактор витрин</button></div><div id="admin-content"></div>';if(adminTab==='products')$('#admin-content').innerHTML=db.products.length?'<div class="panel"><table class="table"><thead><tr><th>Товар</th><th>Стоимость</th><th></th></tr></thead><tbody>'+db.products.map(p=>'<tr><td><span class="tiny-art">'+art(p)+'</span>'+esc(p.name)+'</td><td>'+p.price+' КК</td><td><button class="secondary" data-edit-product="'+p.id+'">Открыть</button></td></tr>').join('')+'</tbody></table></div>':'<div class="panel empty">Товаров пока нет. Добавьте первый товар.</div>';else{const live=db.showcases.find(s=>s.id===db.published);$('#admin-content').innerHTML='<h2 style="font-size:15px">Опубликованная витрина</h2>'+(live?showcaseRow(live,true):'<div class="panel empty">Нет опубликованной витрины</div>')+'<div class="divider">Другие витрины</div>'+db.showcases.filter(s=>s.id!==db.published).map(s=>showcaseRow(s,false)).join('')+(db.showcases.every(s=>s.id===db.published)?'<div class="empty">Других витрин пока нет</div>':'')}}
function showcaseRow(s,live){return '<div class="showcase-row '+(live?'live':'')+'"><div><h3>'+esc(s.name)+'</h3><p>'+s.items.length+' товаров'+(live?' · Опубликована':' · Не опубликована')+'</p></div><div class="row-actions"><button class="secondary" data-edit-showcase="'+s.id+'">Редактирование</button><button class="danger" data-delete-showcase="'+s.id+'">Удалить витрину</button>'+(live?'':'<button class="primary" data-publish="'+s.id+'">Опубликовать</button>')+'</div></div>'}
function modal(title,body,wide=false){$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML='<div class="modal-head"><h2>'+esc(title)+'</h2><button class="close" data-close aria-label="Закрыть">×</button></div>'+body;if(!$('#modal').open)$('#modal').showModal()}
function login(){modal('Вход для администратора','<form id="login-form"><label for="login">Логин</label><input id="login" name="login" autocomplete="username" required><label for="password">Пароль</label><input id="password" name="password" type="password" autocomplete="current-password" required><div class="error" id="login-error" role="alert"></div><p class="note">Демо-вход: <strong>admin / admin</strong><br>Подключение существующего входа — на следующем этапе.</p><div class="form-actions"><button type="button" class="secondary" data-close>Отмена</button><button class="primary">Войти</button></div></form>');$('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('login')==='admin'&&f.get('password')==='admin'){admin=true;page='admin';$('#modal').close();render()}else $('#login-error').textContent='Неверный логин или пароль.'}}
function editProduct(id){if(!admin)return;const p=db.products.find(p=>p.id===id)||{name:'',description:'',price:0,image:'',art:'plush'};modal(id?'Карточка товара':'Новый товар','<form id="product-form"><label for="product-name">Название</label><input id="product-name" name="name" maxlength="80" required value="'+esc(p.name)+'"><label for="description">Описание</label><textarea id="description" name="description" rows="3" maxlength="300" required>'+esc(p.description)+'</textarea><label for="price">Стоимость в КК</label><input id="price" name="price" type="number" min="0" step="1" max="1000000" required value="'+p.price+'"><label for="image">Изображение товара</label><input id="image" type="file" accept="image/png,image/jpeg,image/webp"><div class="note">PNG, JPG или WebP, до 3 МБ.</div><div id="image-preview" class="tiny-art" style="height:100px;margin-top:10px">'+art(p)+'</div><div class="error" id="product-error" role="alert"></div><div class="form-actions">'+(id?'<button type="button" class="danger" data-delete-product="'+id+'">Удалить</button>':'')+'<button type="button" class="secondary" data-close>Отмена</button><button class="primary">Сохранить</button></div></form>');let image=p.image,reading=false;$('#image').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('#product-error').textContent='';if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3*1024*1024){$('#product-error').textContent='Выберите PNG, JPG или WebP размером до 3 МБ.';e.target.value='';return}reading=true;try{image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});$('#image-preview').innerHTML=art({...p,image})}catch{$('#product-error').textContent='Не удалось загрузить изображение.'}finally{reading=false}};$('#product-form').onsubmit=e=>{e.preventDefault();if(reading){$('#product-error').textContent='Дождитесь загрузки изображения.';return}const f=new FormData(e.target),name=f.get('name').trim(),description=f.get('description').trim();if(!name||!description){$('#product-error').textContent='Заполните название и описание.';return}const product={...p,id:id||'p'+crypto.randomUUID(),name,description,price:Number(f.get('price')),image};if(mutate(d=>{const i=d.products.findIndex(p=>p.id===product.id);if(i>=0)d.products[i]=product;else d.products.push(product)})){$('#modal').close();render();toast('Товар сохранён')}}}
function editShowcase(id){if(!admin)return;const s=db.showcases.find(s=>s.id===id);editingShowcase=id||null;draftItems=s?[...s.items]:[];modal(s?'Редактирование витрины':'Новая витрина','<form id="showcase-form"><label for="showcase-name">Название витрины</label><input id="showcase-name" maxlength="80" required value="'+esc(s?.name||'')+'"><p class="note">Перенесите товары кнопками + и − или перетащите их между областями.</p><div class="transfer"><div class="transfer-zone" id="all-products" data-zone="all"></div><div class="transfer-zone target" id="selected-products" data-zone="selected"></div></div><div class="error" id="showcase-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary" data-close>Отмена</button><button class="primary">Сохранить витрину</button></div></form>',true);renderTransfer();document.querySelectorAll('[data-zone]').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!db.products.some(p=>p.id===id))return;transfer(id,z.dataset.zone==='selected')}});$('#showcase-form').onsubmit=e=>{e.preventDefault();const name=$('#showcase-name').value.trim();if(!name){$('#showcase-error').textContent='Введите название витрины.';return}if(mutate(d=>{const obj={id:editingShowcase||'s'+crypto.randomUUID(),name,items:[...draftItems]};const i=d.showcases.findIndex(s=>s.id===obj.id);if(i>=0)d.showcases[i]=obj;else d.showcases.push(obj)})){$('#modal').close();render();toast('Витрина сохранена')}}}
function renderTransfer(){const item=(p,chosen)=>'<div class="transfer-item" draggable="true" data-drag="'+p.id+'"><span>'+esc(p.name)+'<small class="muted" style="display:block;margin-top:4px">'+p.price+' КК</small></span><button type="button" data-transfer="'+p.id+'" data-add="'+!chosen+'" aria-label="'+(chosen?'Убрать':'Добавить')+' '+esc(p.name)+'">'+(chosen?'−':'+')+'</button></div>';const available=db.products.filter(p=>!draftItems.includes(p.id)),chosen=draftItems.map(id=>db.products.find(p=>p.id===id)).filter(Boolean);$('#all-products').innerHTML='<h3>Все товары · '+available.length+'</h3>'+available.map(p=>item(p,false)).join('')+(!available.length?'<div class="empty">Все товары перенесены</div>':'');$('#selected-products').innerHTML='<h3>Товары для витрины · '+chosen.length+'</h3>'+chosen.map(p=>item(p,true)).join('')+(!chosen.length?'<div class="empty">Перенесите товары сюда</div>':'');document.querySelectorAll('[data-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag))}
function transfer(id,add){if(add&&!draftItems.includes(id))draftItems.push(id);if(!add)draftItems=draftItems.filter(x=>x!==id);renderTransfer()}
function confirmAction(title,message,fn){modal(title,'<p>'+esc(message)+'</p><div class="form-actions"><button class="secondary" data-close>Отмена</button><button class="danger" id="confirm-action">Удалить</button></div>');$('#confirm-action').onclick=()=>{if(fn()){$('#modal').close();render()}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){$('#modal').close();return}if(b.dataset.page){page=b.dataset.page;render();return}if(b.dataset.child){selected=Number(b.dataset.child);query=displayChildName(children.find(c=>c.id===selected));$('#search').value=query;listChildren();profile();return}if(!admin)return;if(b.dataset.tab){adminTab=b.dataset.tab;render();return}if(b.dataset.action==='add-product')editProduct();if(b.dataset.action==='add-showcase')editShowcase();if(b.dataset.editProduct)editProduct(b.dataset.editProduct);if(b.dataset.editShowcase)editShowcase(b.dataset.editShowcase);if(b.dataset.transfer)transfer(b.dataset.transfer,b.dataset.add==='true');if(b.dataset.publish){if(mutate(d=>d.published=b.dataset.publish)){render();toast('Витрина опубликована. Предыдущая перемещена в другие витрины.')}}if(b.dataset.deleteProduct){const id=b.dataset.deleteProduct,p=db.products.find(p=>p.id===id);confirmAction('Удалить товар?',p.name+' будет удалён из списка товаров и всех витрин.',()=>mutate(d=>{d.products=d.products.filter(p=>p.id!==id);d.showcases.forEach(s=>s.items=s.items.filter(x=>x!==id))}))}if(b.dataset.deleteShowcase){const id=b.dataset.deleteShowcase,s=db.showcases.find(s=>s.id===id);confirmAction('Удалить витрину?',s.name+(id===db.published?' будет удалена. Опубликованной витрины не останется.':' будет удалена. Товары сохранятся.'),()=>mutate(d=>{d.showcases=d.showcases.filter(s=>s.id!==id);if(d.published===id)d.published=null}))}});
$('#admin-entry').onclick=()=>{if(admin&&page!=='admin'){page='admin';render()}else if(admin){admin=false;page='account';render();toast('Вы вышли из админской части')}else login()};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('storage',e=>{if(e.key==='capybara-demo-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(Array.isArray(next.products)&&Array.isArray(next.showcases)){db=upgradeCatalog(next);try{const cleaned=JSON.stringify(db);if(cleaned!==e.newValue)localStorage.setItem('capybara-demo-v1',cleaned)}catch{}render();if($('#modal').open){$('#modal').close();toast('Данные обновлены в другой вкладке. Откройте карточку заново.')}}}catch{}}});
render();
